ffi_fn ! { #[doc = " Polls the executor, trying to make progress on any tasks that can do so."] #[doc = ""] #[doc = " If any task from the executor is ready, returns one of them. The way"] #[doc = " tasks signal being finished is internal to Hyper. The order in which tasks"] #[doc = " are returned is not guaranteed. Use userdata to distinguish between tasks."] #[doc = ""] #[doc = " To avoid a memory leak, the task must eventually be consumed by"] #[doc = " `hyper_task_free`."] #[doc = ""] #[doc = " If there are no ready tasks, this returns `NULL`."] fn hyper_executor_poll (exec : * const hyper_executor) -> * mut hyper_task { let exec = non_null ! (&* exec ?= ptr :: null_mut ()) ; match exec . poll_next () { Some (task) => Box :: into_raw (task) , None => ptr :: null_mut () ,}
} ?= ptr :: null_mut () }